api={'openapi':'3.1.0','info':{'title':'Galung.id Platform API','version':'1.0.0','description':'Contract for Galung Basic/Pro MVP, manual bank transfer only. Draft for engineering review; no payment gateway. JSON is camelCase while PostgreSQL is snake_case.'},'servers':[{'url':'https://api.galung.id/api/v1','description':'Production (planned)'},{'url':'https://staging-api.galung.id/api/v1','description':'Staging (planned)'}],'tags':[{'name':x} for x in ['Public','Auth','Account','Commerce','Payments','Subscriptions','Licensing','Desktop Licensing','Downloads','Admin Finance','Admin Licenses','Admin Catalog','Admin CMS','Admin System']],'paths':{},'components':{'securitySchemes':{'cookieAuth':{'type':'apiKey','in':'cookie','name':'galung_session','description':'HttpOnly Secure server session. Mutations additionally require CSRF verification.'},'csrfToken':{'type':'apiKey','in':'header','name':'X-CSRF-Token'},'desktopBearer':{'type':'http','scheme':'bearer','bearerFormat':'opaque device-bound token'}},'schemas':schemas,'parameters':{'UUID':{'name':'id','in':'path','required':True,'schema':{'type':'string','format':'uuid'}},'Cursor':{'name':'cursor','in':'query','schema':{'type':'string'}},'Limit':{'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':100,'default':20}},'Idempotency':{'name':'Idempotency-Key','in':'header','required':True,'schema':{'type':'string','minLength':16,'maxLength':128}},'CSRF':{'name':'X-CSRF-Token','in':'header','required':True,'schema':{'type':'string'}}}}}
common_errors={str(x):{'description':y,'content':{'application/json':{'schema':S('Error')}}} for x,y in [(400,'Malformed request'),(401,'Not authenticated'),(403,'Forbidden'),(404,'Not found or inaccessible'),(409,'State conflict'),(422,'Validation/business rule failed'),(429,'Rate limited'),(500,'Internal error')]}
def add(method,path,tag,summary,resp=None,body=None,auth='cookie',idem=False,csrf=None,params=None,status='200',notes=None):
 op={'tags':[tag],'summary':summary,'operationId':method.lower()+'_'+path.strip('/').replace('/','_').replace('{','').replace('}','').replace('-','_'),'responses':{status:{'description':'Success'}}}
 if notes:op['description']=notes
 if resp:op['responses'][status]['content']={'application/json':{'schema':S(resp) if isinstance(resp,str) else resp}}
 if body:op['requestBody']={'required':True,'content':{'application/json':{'schema':S(body) if isinstance(body,str) else body}}}
 if auth=='cookie':op['security']=[{'cookieAuth':[]}]
 elif auth=='desktop':op['security']=[{'desktopBearer':[]}]
 elif auth=='public':op['security']=[]
 if csrf is None:csrf=auth=='cookie' and method.lower() in ('post','put','patch','delete')
 q=list(params or [])
 if idem:q.append({'$ref':'#/components/parameters/Idempotency'})
 if csrf:q.append({'$ref':'#/components/parameters/CSRF'})
 if q:op['parameters']=q
 if auth!='public': op['responses'].update({k:v for k,v in common_errors.items() if k in ['401','403','409','422','429','500']})
 else:op['responses'].update({k:v for k,v in common_errors.items() if k in ['400','422','429','500']})
 api['paths'].setdefault(path,{})[method.lower()]=op
