for path,item in api['paths'].items():
 if not path.startswith('/admin/'): continue
 for method,op in item.items():
  if method not in ('get','post','patch','put','delete'): continue
  if path.startswith('/admin/payment-submissions/') and path.endswith('/approve'): perm='finance.approve'
  elif path.startswith('/admin/bank-credits'): perm='bank.credit.record'
  elif path.startswith('/admin/bank-account-change-requests'):
   perm='bank.change.approve' if path.endswith('/approve-and-publish') else 'bank.change.request'
  elif path.startswith('/admin/license-issuance/') and path.endswith('/issue'): perm='license.issue'
  elif path.startswith('/admin/licenses/') and path.endswith('/revoke'): perm='license.revoke'
  elif path.startswith('/admin/cms/'): perm='cms.publish' if path.endswith('/publish') else 'cms.write'
  elif path.startswith('/admin/software-releases'): perm='release.publish'
  else: perm='role-scoped; specify exact permission before freeze'
  op['x-required-permission']=perm
